/// Sorted allow-list of `fam` (nullptr / 0 for NONE and UNIT_NODESC).
inline const uint16_t *installer_allow_list(sungrow_modbus::XmlFamily fam, size_t *n) {
  switch (fam) {
    case sungrow_modbus::XmlFamily::STR_PV:
      *n = sizeof(INSTALLER_ALLOW_STR_PV) / sizeof(uint16_t);
      return INSTALLER_ALLOW_STR_PV;
    case sungrow_modbus::XmlFamily::RES_ES:
      *n = sizeof(INSTALLER_ALLOW_RES_ES) / sizeof(uint16_t);
      return INSTALLER_ALLOW_RES_ES;
    case sungrow_modbus::XmlFamily::RES_NEW_PV:
      *n = sizeof(INSTALLER_ALLOW_RES_NEW_PV) / sizeof(uint16_t);
      return INSTALLER_ALLOW_RES_NEW_PV;
    case sungrow_modbus::XmlFamily::UNIT:
      *n = sizeof(INSTALLER_ALLOW_UNIT) / sizeof(uint16_t);
      return INSTALLER_ALLOW_UNIT;
    default:
      *n = 0;
      return nullptr;
  }
}

/// True if `addr` may be written to a device of XML family `fam` (binary search).
inline bool installer_addr_allowed(sungrow_modbus::XmlFamily fam, uint16_t addr) {
  size_t n = 0;
  const uint16_t *a = installer_allow_list(fam, &n);
  size_t lo = 0, hi = n;
  while (lo < hi) {
    size_t mid = (lo + hi) / 2;
    if (a[mid] < addr)
      lo = mid + 1;
    else
      hi = mid;
  }
  return lo < n && a[lo] == addr;
}

